from pathlib import Path
p=Path("src/App.tsx")
s=p.read_text(encoding="utf-8")

def replace_function(text,start_marker,end_marker,new_code):
    start=text.find(start_marker)
    if start<0: raise SystemExit(f"Inizio non trovato: {start_marker}")
    end=text.find(end_marker,start)
    if end<0: raise SystemExit(f"Fine non trovata: {end_marker}")
    return text[:start]+new_code+"\n"+text[end:]

# Interfaces and coach calculations
anchor='interface Store{'
coach_types='''interface CoachCareer{name:string;seasons:string[];matches:number;wins:number;draws:number;losses:number;points:number;pointsPerGame:number;winPct:number;goalsFor:number;goalsAgainst:number;goalDifference:number;goalsForPerGame:number;goalsAgainstPerGame:number;bestSeasonId?:string;bestSeasonLabel?:string;bestSeasonPpg:number;cupWins:number;seasonRows:{seasonId:string;seasonLabel:string;matches:number;wins:number;draws:number;losses:number;points:number;pointsPerGame:number;goalsFor:number;goalsAgainst:number;goalDifference:number}[]}\n'''
if 'interface CoachCareer' not in s:
    s=s.replace(anchor,coach_types+anchor)

anchor='const seasonParam='
coach_calc='''function coachCareers(d:Store):CoachCareer[]{const rows=new Map<string,{name:string;seasonId:string;seasonLabel:string;matches:MatchRow[]}>();for(const m of d.matches.filter(official)){const season=d.seasons.find(x=>x.id===m.seasonId),name=(m.coach||season?.coach||"").trim();if(!name)continue;const key=`${name}__${m.seasonId}`,current=rows.get(key)||{name,seasonId:m.seasonId,seasonLabel:season?.label||m.seasonLabel,matches:[]};current.matches.push(m);rows.set(key,current)}const names=[...new Set([...rows.values()].map(x=>x.name))];return names.map(name=>{const seasonRows=[...rows.values()].filter(x=>x.name===name).map(x=>{const wins=x.matches.filter(m=>m.goalsFor>m.goalsAgainst).length,draws=x.matches.filter(m=>m.goalsFor===m.goalsAgainst).length,losses=x.matches.length-wins-draws,points=wins*3+draws,gf=x.matches.reduce((a,m)=>a+m.goalsFor,0),ga=x.matches.reduce((a,m)=>a+m.goalsAgainst,0);return{seasonId:x.seasonId,seasonLabel:x.seasonLabel,matches:x.matches.length,wins,draws,losses,points,pointsPerGame:x.matches.length?points/x.matches.length:0,goalsFor:gf,goalsAgainst:ga,goalDifference:gf-ga}}).sort((a,b)=>b.pointsPerGame-a.pointsPerGame||b.matches-a.matches),matches=seasonRows.reduce((a,x)=>a+x.matches,0),wins=seasonRows.reduce((a,x)=>a+x.wins,0),draws=seasonRows.reduce((a,x)=>a+x.draws,0),losses=seasonRows.reduce((a,x)=>a+x.losses,0),points=seasonRows.reduce((a,x)=>a+x.points,0),gf=seasonRows.reduce((a,x)=>a+x.goalsFor,0),ga=seasonRows.reduce((a,x)=>a+x.goalsAgainst,0),best=seasonRows[0];return{name,seasons:seasonRows.map(x=>x.seasonId),matches,wins,draws,losses,points,pointsPerGame:matches?points/matches:0,winPct:matches?wins/matches:0,goalsFor:gf,goalsAgainst:ga,goalDifference:gf-ga,goalsForPerGame:matches?gf/matches:0,goalsAgainstPerGame:matches?ga/matches:0,bestSeasonId:best?.seasonId,bestSeasonLabel:best?.seasonLabel,bestSeasonPpg:best?.pointsPerGame||0,cupWins:d.seasons.filter(se=>se.coach===name&&/vint|campion|1°|primo/i.test(se.cupResult||"")).length,seasonRows}})}\n'''
if 'function coachCareers' not in s:
    s=s.replace(anchor,coach_calc+anchor)

players='''function Players({d}:{d:Store}){const[q,setQ]=useSearchParams(),search=q.get("q")||"",selected=seasonParam(q.get("seasons")),competition=q.get("competition")||"all",kind=q.get("kind")||"all",sort=(q.get("sort")||"appearances") as SortKey,dir=(q.get("dir")||"desc") as Dir;let rows=filteredCareers(d,selected,competition);if(search)rows=rows.filter(x=>x.displayName.toLowerCase().includes(search.toLowerCase()));if(kind==="keepers")rows=rows.filter(x=>x.isKeeper);if(kind==="outfield")rows=rows.filter(x=>!x.isKeeper);rows.sort((a,b)=>{const av=a[sort],bv=b[sort],c=typeof av==="string"?av.localeCompare(String(bv),"it"):Number(av)-Number(bv);return dir==="asc"?c:-c});const set=(k:string,v:string)=>{const z=new URLSearchParams(q);v&&v!=="all"?z.set(k,v):z.delete(k);setQ(z)},toggle=(id:string)=>{const x=new Set(selected);x.has(id)?x.delete(id):x.add(id);set("seasons",[...x].join(","))},quick=(value:number|"all"|"none")=>set("seasons",value==="all"?d.seasons.map(x=>x.id).join(","):value==="none"?"":d.seasons.slice(0,value).map(x=>x.id).join(",")),order=(key:SortKey)=>{const z=new URLSearchParams(q),nextDir=sort===key&&dir==="desc"?"asc":"desc";z.set("sort",key);z.set("dir",nextDir);setQ(z)};const cols:[SortKey,string][]=[["displayName","Giocatore"],["appearances","Presenze"],["goals","Gol"],["assists","Assist"],["contributions","G+A"],["goalsPerGame","Gol/P"],["assistsPerGame","Assist/P"],["contributionsPerGame","G+A/P"],["seasons","Stagioni"],["starterApps","Titolare"],["subApps","Subentrato"],["starterPct","% titolare"]];return <><Crumbs items={[{label:"Archivio",to:"/"},{label:"Giocatori"}]}/><Title>Giocatori</Title><div className="season-multiselect"><div className="season-quick"><button onClick={()=>quick("all")}>Tutte</button><button onClick={()=>quick("none")}>Nessuna</button><button onClick={()=>quick(2)}>Ultime 2</button><button onClick={()=>quick(3)}>Ultime 3</button></div>{d.seasons.map(se=><label key={se.id}><input type="checkbox" checked={!selected.length||selected.includes(se.id)} onChange={()=>toggle(se.id)}/>{se.label}</label>)}</div><div className="filterbar advanced"><label><Search size={16}/><input placeholder="Cerca giocatore" value={search} onChange={e=>set("q",e.target.value)}/></label><select value={competition} onChange={e=>set("competition",e.target.value)}><option value="all">Tutte le competizioni</option><option value="league">Campionato</option><option value="playoff">Playoff</option><option value="playout">Playout</option><option value="cup">Coppa</option><option value="friendly">Amichevoli</option></select><select value={kind} onChange={e=>set("kind",e.target.value)}><option value="all">Tutti</option><option value="outfield">Movimento</option><option value="keepers">Portieri</option></select><button onClick={()=>setQ({})}>Azzera filtri</button></div><p className="data-note">Primo clic: valori più alti. Secondo clic: valori più bassi.</p><div className="tablewrap stats-table"><table><thead><tr><th className="rank-col">#</th>{cols.map(([key,label])=><th className={key==="displayName"?"name-col":""} key={key}><button className="sortbtn" onClick={()=>order(key)}>{label}{sort===key&&(dir==="desc"?<ArrowDown size={14}/>:<ArrowUp size={14}/>)}</button></th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={r.playerId}><td className="rank-col">{i+1}</td>{cols.map(([key])=><td className={key==="displayName"?"name-col":""} key={key}>{key==="displayName"?<Link to={`/giocatori/${r.playerId}`}><b>{r.displayName}</b></Link>:key.endsWith("Pct")?`${n(Number(r[key])*100,1)}%`:key.includes("Per")?n(Number(r[key])):r[key] as number}</td>)}</tr>)}</tbody></table></div></>}'''
s=replace_function(s,'function Players(','function PlayerChart(',players)

season_rank='''function SeasonPlayerRanking({d,seasonId}:{d:Store;seasonId:string}){const[q,setQ]=useSearchParams(),filterKey=`seasonCompetition_${seasonId}`,sortKey=`seasonSort_${seasonId}`,dirKey=`seasonDir_${seasonId}`,competition=q.get(filterKey)||"all",sort=(q.get(sortKey)||"appearances") as SortKey,dir=(q.get(dirKey)||"desc") as Dir,rows=filteredCareers(d,[seasonId],competition).sort((a,b)=>{const av=a[sort],bv=b[sort],c=typeof av==="string"?av.localeCompare(String(bv),"it"):Number(av)-Number(bv);return dir==="asc"?c:-c});const setCompetition=(v:string)=>{const z=new URLSearchParams(q);v==="all"?z.delete(filterKey):z.set(filterKey,v);setQ(z)},order=(key:SortKey)=>{const z=new URLSearchParams(q),next=sort===key&&dir==="desc"?"asc":"desc";z.set(sortKey,key);z.set(dirKey,next);setQ(z)};const cols:[SortKey,string][]=[["displayName","Giocatore"],["appearances","Presenze"],["goals","Gol"],["assists","Assist"],["contributions","G+A"],["goalsPerGame","Gol/P"],["assistsPerGame","Assist/P"],["contributionsPerGame","G+A/P"],["starterApps","Titolare"],["subApps","Subentrato"],["starterPct","% titolare"]];return <><h2 className="sectiontitle">Classifica giocatori della stagione</h2><div className="filterbar"><select value={competition} onChange={e=>setCompetition(e.target.value)}><option value="all">Tutte le competizioni</option><option value="league">Campionato</option><option value="playoff">Playoff</option><option value="playout">Playout</option><option value="cup">Coppa</option><option value="friendly">Amichevoli</option></select></div><div className="tablewrap stats-table"><table><thead><tr><th className="rank-col">#</th>{cols.map(([key,label])=><th className={key==="displayName"?"name-col":""} key={key}><button className="sortbtn" onClick={()=>order(key)}>{label}{sort===key&&(dir==="desc"?<ArrowDown size={14}/>:<ArrowUp size={14}/>)}</button></th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={r.playerId}><td className="rank-col">{i+1}</td>{cols.map(([key])=><td className={key==="displayName"?"name-col":""} key={key}>{key==="displayName"?<Link to={`/giocatori/${r.playerId}`}><b>{r.displayName}</b></Link>:key.endsWith("Pct")?`${n(Number(r[key])*100,1)}%`:key.includes("Per")?n(Number(r[key])):r[key] as number}</td>)}</tr>)}</tbody></table></div></>}'''
s=replace_function(s,'function SeasonPlayerRanking(','function SeasonDetail(',season_rank)

coaches='''function Coaches({d}:{d:Store}){const rows=coachCareers(d).sort((a,b)=>b.matches-a.matches||b.pointsPerGame-a.pointsPerGame);return <><Crumbs items={[{label:"Archivio",to:"/"},{label:"Allenatori"}]}/><Title>Allenatori</Title><p className="data-note">Statistiche sulle partite ufficiali associate all’allenatore nella partita o, in mancanza, nella stagione.</p><div className="tablewrap coach-table"><table><thead><tr><th className="name-col">Allenatore</th><th>Stagioni</th><th>Partite</th><th>V</th><th>N</th><th>P</th><th>% vittorie</th><th>Punti/P</th><th>GF/P</th><th>GS/P</th><th>DR</th></tr></thead><tbody>{rows.map(r=><tr key={r.name}><td className="name-col"><Link to={`/allenatori/${encodeURIComponent(r.name)}`}><b>{r.name}</b></Link></td><td>{r.seasons.length}</td><td>{r.matches}</td><td>{r.wins}</td><td>{r.draws}</td><td>{r.losses}</td><td>{n(r.winPct*100,1)}%</td><td>{n(r.pointsPerGame)}</td><td>{n(r.goalsForPerGame)}</td><td>{n(r.goalsAgainstPerGame)}</td><td>{r.goalDifference}</td></tr>)}</tbody></table></div></>}
function CoachDetail({d}:{d:Store}){const{name}=useParams(),coach=coachCareers(d).find(x=>x.name===decodeURIComponent(name||""));if(!coach)return <p>Allenatore non trovato.</p>;return <><Crumbs items={[{label:"Archivio",to:"/"},{label:"Allenatori",to:"/allenatori"},{label:coach.name}]}/><Title>{coach.name}</Title><div className="metricgrid"><Metric v={coach.matches} l="Partite ufficiali"/><Metric v={coach.wins} l="Vittorie"/><Metric v={`${n(coach.winPct*100,1)}%`} l="Percentuale vittorie"/><Metric v={n(coach.pointsPerGame)} l="Punti per partita"/><Metric v={coach.goalDifference} l="Differenza reti"/><Metric v={coach.seasons.length} l="Stagioni"/></div><h2 className="sectiontitle">Stagione per stagione</h2><div className="tablewrap coach-table"><table><thead><tr><th className="name-col">Stagione</th><th>Partite</th><th>V</th><th>N</th><th>P</th><th>Punti/P</th><th>GF</th><th>GS</th><th>DR</th></tr></thead><tbody>{coach.seasonRows.map(r=><tr key={r.seasonId}><td className="name-col"><Link to={`/stagioni/${r.seasonId}`}><b>{r.seasonLabel}</b></Link></td><td>{r.matches}</td><td>{r.wins}</td><td>{r.draws}</td><td>{r.losses}</td><td>{n(r.pointsPerGame)}</td><td>{r.goalsFor}</td><td>{r.goalsAgainst}</td><td>{r.goalDifference}</td></tr>)}</tbody></table></div></>}'''
if 'function Coaches(' not in s:
    s=s.replace('function Seasons(',coaches+'\nfunction Seasons(')

# Navigation and routes
s=s.replace('<Link to="/giocatori">Giocatori</Link><Link to="/partite">Partite</Link>','<Link to="/giocatori">Giocatori</Link><Link to="/allenatori">Allenatori</Link><Link to="/partite">Partite</Link>')
s=s.replace('<Route path="/partite" element={<Matches d={d}/>}/>','<Route path="/allenatori" element={<Coaches d={d}/>}/><Route path="/allenatori/:name" element={<CoachDetail d={d}/>}/><Route path="/partite" element={<Matches d={d}/>}/>')

# Coach records inserted before Records closes: insert cards after title
needle='<Title>Record</Title>'
coach_record='''<Title>Record</Title>{coachCareers(d).length>0&&<><h2 className="recordgroup">Record allenatori</h2><p className="data-note">Le medie richiedono almeno 10 partite ufficiali.</p><div className="cards recordcards">{(()=>{const coaches=coachCareers(d),eligible=coaches.filter(x=>x.matches>=10),mostMatches=[...coaches].sort((a,b)=>b.matches-a.matches)[0],mostWins=[...coaches].sort((a,b)=>b.wins-a.wins)[0],bestPpg=[...eligible].sort((a,b)=>b.pointsPerGame-a.pointsPerGame)[0],bestWin=[...eligible].sort((a,b)=>b.winPct-a.winPct)[0];return <><CoachRec t="Più partite" c={mostMatches} v={mostMatches?.matches||0}/><CoachRec t="Più vittorie" c={mostWins} v={mostWins?.wins||0}/><CoachRec t="Miglior media punti" c={bestPpg} v={n(bestPpg?.pointsPerGame||0)}/><CoachRec t="Migliore % vittorie" c={bestWin} v={`${n((bestWin?.winPct||0)*100,1)}%`}/></>})()}</div></>}'''
if 'Record allenatori' not in s:
    s=s.replace(needle,coach_record,1)
anchor='const Rec='
coach_rec='''const CoachRec=({t,c,v}:{t:string;c?:CoachCareer;v:string|number})=><Link className="card cardlink gold" to={c?`/allenatori/${encodeURIComponent(c.name)}`:"#"}><h3>{t}</h3><strong>{v}</strong><p>{c?.name}</p></Link>;'''
if 'const CoachRec=' not in s:
    s=s.replace(anchor,coach_rec+'\n'+anchor)

p.write_text(s,encoding="utf-8")
print("PATCH FRONTEND V15 OK")
